const AppError = require('../../utils/appError');

/**
 * Validates output generated by transcription provider
 */
const validateTranscriptionResult = (result) => {
  if (!result || typeof result !== 'object') {
    throw new AppError('Transcription result is invalid or empty.', 500, 'TRANSCRIPTION_VALIDATION_ERROR');
  }

  if (typeof result.rawText !== 'string' || result.rawText.trim().length === 0) {
    throw new AppError('Transcription generated empty text.', 500, 'TRANSCRIPTION_EMPTY_TEXT');
  }

  if (!Array.isArray(result.segments) || result.segments.length === 0) {
    throw new AppError('Transcription produced zero segments.', 500, 'TRANSCRIPTION_NO_SEGMENTS');
  }

  result.segments.forEach((seg, idx) => {
    if (typeof seg.text !== 'string' || !seg.text.trim()) {
      throw new AppError(`Transcript segment [${idx}] contains empty text.`, 500, 'INVALID_SEGMENT_TEXT');
    }
    if (typeof seg.startTime !== 'number' || typeof seg.endTime !== 'number' || seg.endTime < seg.startTime) {
      throw new AppError(`Transcript segment [${idx}] has invalid timing stamps.`, 500, 'INVALID_SEGMENT_TIMING');
    }
  });

  return true;
};

module.exports = {
  validateTranscriptionResult,
};
